package com.shale.data.dao;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.*;
import org.junit.jupiter.api.Test;
final class FieldConfirmationPhase2BContractTest {
 private static final Path ROOT=Path.of("..").toAbsolutePath().normalize();
 private static String read(String p)throws Exception{return Files.readString(ROOT.resolve(p)).replace("\r\n","\n");}
 @Test void deployedPhase2aCheckUsesDynamicSqlAfterColumnAddition()throws Exception{assertTrue(read("docs/sql/2026-09-23_field_confirmation_foundation_phase2a.sql").contains("EXEC sys.sp_executesql N'ALTER TABLE dbo.CaseDates WITH CHECK ADD CONSTRAINT CK_CaseDates_ValueRevision"));}
 @Test void policyIsIndependentVersionedConcurrentTenantAdminAndAudited()throws Exception{String s=read("shale-data/src/main/java/com/shale/data/dao/FieldConfirmationDao.java");assertAll(()->assertFalse(s.contains("IsRequired")),()->assertTrue(s.contains("SupersededAt=SYSUTCDATETIME()")),()->assertTrue(s.contains("expectedPolicyRowVer")),()->assertTrue(s.contains("is_admin=1")),()->assertTrue(s.contains("requireActiveRole")),()->assertTrue(s.contains("FIELD_CONFIRMATION_POLICY")),()->assertFalse(s.contains("CaseTeam")));}
 @Test void authoritativeEligibilitySupportsBuiltInsAndCustomAssignmentsOnly()throws Exception{String s=read("shale-data/src/main/java/com/shale/data/dao/FieldConfirmationDao.java");assertAll(()->assertTrue(s.contains("r.SystemKey='ADMIN' AND u.is_admin=1")),()->assertTrue(s.contains("r.SystemKey='ATTORNEY' AND u.is_attorney=1")),()->assertTrue(s.contains("UserFirmWideRoleAssignments")),()->assertTrue(s.contains("SESSION_CONTEXT(N'PrincipalUserId')")));}
 @Test void allDateWritersUseOneParticipantAndBusinessRevisionRules()throws Exception{String s=read("shale-data/src/main/java/com/shale/data/dao/CaseDateDao.java");assertAll(()->assertTrue(count(s,"evaluateCaseDate(")>=5),()->assertTrue(s.contains("ValueRevision=ValueRevision+?")),()->assertTrue(s.contains("ValueRevision=ValueRevision+1")),()->assertTrue(s.contains("businessChanged")),()->assertTrue(s.contains("before.typeId!=c.caseDateTypeId()")));}
 @Test void manualConfirmationRejectsDeletedStaleWrongRoleAndAuditsAtomically()throws Exception{String s=read("shale-data/src/main/java/com/shale/data/dao/FieldConfirmationDao.java");assertAll(()->assertTrue(s.contains("cd.IsDeleted=0")),()->assertTrue(s.contains("expectedBusinessValueRevision")),()->assertTrue(s.contains("expectedRequirementRowVer")),()->assertTrue(s.contains("if(!hasRole")),()->assertTrue(s.contains("SAVED_VALUE_CONFIRMATION")),()->assertTrue(s.contains("con.rollback()")));}
 @Test void phase2cReadsAndEligibilityDelegateThroughProductionAdapter()throws Exception{String s=read("shale-data/src/main/java/com/shale/data/service/adapter/CaseServiceAdapter.java");assertAll(()->assertTrue(s.contains("fieldConfirmationDao.listPolicies"),"Settings must read the Phase 2B authority"),()->assertTrue(s.contains("fieldConfirmationDao.listRoles"),"the selector must contain firm-wide roles"),()->assertTrue(s.contains("fieldConfirmationDao.actorHasRole"),"visibility is based on authoritative eligibility"));}
 @Test void migrationAndVerificationAreForwardOnlyAndReadOnly()throws Exception{String m=read("docs/sql/2026-09-24_field_confirmation_audit_allowlist_phase2b.sql"),v=read("docs/sql/2026-09-24_field_confirmation_phase2b_verify.sql");assertAll(()->assertTrue(m.contains("sp_executesql")),()->assertFalse(v.contains("REPLACE_WITH")),()->assertFalse(v.matches("(?is).*(INSERT|UPDATE|DELETE|MERGE|ALTER|CREATE|DROP)\\s+dbo\\..*")),()->assertTrue(v.contains("FindingCount")));}
 private static int count(String s,String n){int c=0,p=0;while((p=s.indexOf(n,p))>=0){c++;p+=n.length();}return c;}
}
